/** Families of dynamic settings whose names contain a user chosen part. */
export const DYNAMIC_CLUSTER_SETTING_PATTERNS: readonly RegExp[] = [
  /^logger\./,
  /^archived\./,
  /^cluster\.remote\./,
  /^search\.remote\./,
  /^cluster\.routing\.allocation\.(include|exclude|require)\./,
  /^cluster\.routing\.allocation\.awareness\.force\./,
  /^transport\.tracer\./,
  /^xpack\.notification\./,
];
